 public void releaseUsing(ItemStack stack,Level l,LivingEntity living,int left){if(l.isClientSide||!(living instanceof Player p)||!p.isAlive()||p.isSpectator()||blocked(p)||!stack.is(AddonItems.HG01.get())||p.getUseItem()!=stack||getUseDuration(stack,living)-left<3)return;Vec3 direction=p.getViewVector(1);Vec3 eye=p.getEyePosition(),at=eye.add(direction.scale(.35)).add(0,-.12,0);var hit=l.clip(new net.minecraft.world.level.ClipContext(eye,at,net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,p));if(hit.getType()!=HitResult.Type.MISS)at=eye;var g=AddonEntities.HG01.get().create(l);if(g==null)return;g.arm(p,at,direction.scale(1.5).add(p.getDeltaMovement()));if(!l.addFreshEntity(g))return;if(!p.getAbilities().instabuild)stack.shrink(1);p.getCooldowns().addCooldown(this,10);p.swing(p.getUsedItemHand(),true);l.playSound(null,p.getX(),p.getY(),p.getZ(),net.minecraft.sounds.SoundEvents.SNOWBALL_THROW,net.minecraft.sounds.SoundSource.PLAYERS,.65f,.85f);}
